import { useEffect, useMemo, useState, useDeferredValue, type ClipboardEvent } from 'react';
import { BarChart3, FolderOpen, Plus, RefreshCw, Save, Search, Trash2, Upload, ZoomIn, ZoomOut, Camera, Download, Filter, CheckSquare, Archive, History, RotateCcw, ChevronDown, CheckCircle2, AlertTriangle, XCircle, ClipboardCheck, Database } from 'lucide-react';

type CenterTab = 'dashboard' | 'projects' | 'files' | 'delivery' | 'quality' | 'settings';
type DeliveryRow = Record<string, string | number> & { id: string; cbm: number };
const isDesktop = () => typeof window !== 'undefined' && Boolean(window.rubaDesktop);

const deliveryColumns: Array<{ key: string; label: string; width: string; kind?: 'date' | 'number' }> = [
  { key: 'date', label: 'DATE', width: '110px', kind: 'date' },
  { key: 'season', label: 'SEASON', width: '100px' },
  { key: 'customerCode', label: 'CUSTOMER CODE', width: '170px' },
  { key: 'customerName', label: 'CUSTOMER NAME', width: '250px' },
  { key: 'customerPo', label: 'CUSTOMER PO', width: '260px' },
  { key: 'color', label: 'COLOR', width: '240px' },
  { key: 'dest', label: 'DEST', width: '90px' },
  { key: 'poQty', label: 'PO QTY', width: '110px', kind: 'number' },
  { key: 'targetBooking', label: 'TARGET BOOKING', width: '140px', kind: 'date' },
  { key: 'actualBooking', label: 'ACTUAL BOOKING', width: '140px', kind: 'date' },
  { key: 'targetApproval', label: 'TARGET APPROVAL', width: '145px', kind: 'date' },
  { key: 'approvalReceived', label: 'APPROVAL RECEIVED', width: '150px', kind: 'date' },
  { key: 'pcsPerCtn', label: 'PCS / CTN', width: '110px', kind: 'number' },
  { key: 'packingType', label: 'PACKING TYPE', width: '150px' },
  { key: 'numberOfCarton', label: 'NUMBER OF CARTON', width: '150px', kind: 'number' },
  { key: 'l', label: 'L (cm)', width: '95px', kind: 'number' },
  { key: 'h', label: 'H (cm)', width: '95px', kind: 'number' },
  { key: 'w', label: 'W (cm)', width: '95px', kind: 'number' },
  { key: 'cbm', label: 'CBM', width: '110px', kind: 'number' },
  { key: 'grossWeight', label: 'GROSS KG / CTN', width: '150px', kind: 'number' },
  { key: 'initialShipMode', label: 'INITIAL SHIP MODE', width: '150px' },
  { key: 'targetPl', label: 'TARGET PL', width: '125px', kind: 'date' },
];
const dateKeys = new Set(deliveryColumns.filter(column => column.kind === 'date').map(column => column.key));
const numericKeys = new Set(deliveryColumns.filter(column => column.kind === 'number' && column.key !== 'cbm').map(column => column.key));
const createRow = (): DeliveryRow => Object.fromEntries(deliveryColumns.map(column => [column.key, column.key === 'cbm' ? 0 : ''])) as DeliveryRow;
const normalizeRow = (input: any): DeliveryRow => {
  const row = { ...createRow(), ...(input || {}) } as DeliveryRow;
  row.id = String(input?.id || `delivery_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`);
  for (const key of numericKeys) row[key] = Number(row[key] || 0);
  row.cbm = Number(((Number(row.l) || 0) * (Number(row.h) || 0) * (Number(row.w) || 0)) / 1000000).toFixed(6) as unknown as number;
  return row;
};
const headerAliases: Record<string, string> = {
  date: 'date', season: 'season', 'customer code': 'customerCode', 'customer name': 'customerName', 'customer po': 'customerPo', color: 'color', dest: 'dest', 'po qty': 'poQty', 'target booking': 'targetBooking', 'target date for booking': 'targetBooking', 'actual booking': 'actualBooking', 'actual date for booking': 'actualBooking', 'target approval': 'targetApproval', 'target approval date': 'targetApproval', 'approval received': 'approvalReceived', 'date received approval': 'approvalReceived', 'pcs / ctn': 'pcsPerCtn', 'pcs per ctn': 'pcsPerCtn', 'packing type': 'packingType', 'number of carton': 'numberOfCarton', l: 'l', h: 'h', w: 'w', cbm: 'cbm', 'gross kg / ctn': 'grossWeight', 'gross weight per carton': 'grossWeight', 'initial ship mode': 'initialShipMode', 'target pl': 'targetPl'
};
const normalizeHeader = (value: string) => value.toLowerCase().replace(/[()]/g, '').replace(/_/g, ' ').replace(/\s+/g, ' ').trim();

export default function IndustrialCenter({ onBack, onLoadProject, projectPayload, initialTab = 'dashboard', showTabs = true }: { onBack: () => void; onLoadProject?: (project: any) => Promise<void> | void; projectPayload?: any; initialTab?: CenterTab; showTabs?: boolean }) {
  const [tab, setTab] = useState<CenterTab>(initialTab);
  const [summary, setSummary] = useState({ projects: 0, packingLists: 0, files: 0, deliveryPlans: 0, breakdownRows: 0 });
  const [projects, setProjects] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [search, setSearch] = useState('');
  const [dashboardCustomer, setDashboardCustomer] = useState('');
  const [dashboardStatus, setDashboardStatus] = useState('');
  const [dashboardArchived, setDashboardArchived] = useState<'active' | 'archived' | 'all'>('active');
  const [selectedVersionProject, setSelectedVersionProject] = useState<any>(null);
  const [versions, setVersions] = useState<any[]>([]);
  const [deliverySheet, setDeliverySheet] = useState('');
  const [deliverySheets, setDeliverySheets] = useState<Array<{ name: string; rows: number }>>([]);
  const [deliverySearch, setDeliverySearch] = useState('');
  const [storageRoot, setStorageRoot] = useState('');
  const [projectName, setProjectName] = useState('');
  const [customer, setCustomer] = useState('');
  const [selectedProjectId, setSelectedProjectId] = useState('');
  const [planName, setPlanName] = useState('');
  const [planId, setPlanId] = useState('');
  const [plans, setPlans] = useState<any[]>([]);
  const [rows, setRows] = useState<DeliveryRow[]>([normalizeRow({})]);
  const [deliveryTotal, setDeliveryTotal] = useState(0);
  const [deliveryPage, setDeliveryPage] = useState(0);
  const deliveryPageSize = 250;
  const [filters, setFilters] = useState<Record<string, string>>({});
  const [selectedRows, setSelectedRows] = useState<string[]>([]);
  const [showDeliveryManager, setShowDeliveryManager] = useState(false);
  const [managerRows, setManagerRows] = useState<DeliveryRow[]>([]);
  const [managerTotal, setManagerTotal] = useState(0);
  const [managerPage, setManagerPage] = useState(0);
  const [managerSearch, setManagerSearch] = useState('');
  const [managerSelected, setManagerSelected] = useState<string[]>([]);
  const [zoom, setZoom] = useState(() => Number(localStorage.getItem('ruba_ui_zoom') || 100));
  const [accent, setAccent] = useState(() => localStorage.getItem('ruba_accent') || '#0f766e');
  const [message, setMessage] = useState('');
  const [csvStatus, setCsvStatus] = useState<{ found: boolean; source?: string; modifiedAt?: string; rows?: number; sheets?: Array<{ name: string; rows: number }>; candidates?: string[] }>({ found: false });
  const [breakdownByColor, setBreakdownByColor] = useState<Array<{ color: string; poQty: number }>>([]);
  const deferredDeliverySearch = useDeferredValue(deliverySearch);
  const deferredSearch = useDeferredValue(search);
  const applyDeliveryPayload = (payload: any, preferredSheet = '') => {
    const sheets = Array.isArray(payload?.sheets) ? payload.sheets : [];
    const active = preferredSheet || payload?.activeSheet || sheets[0]?.name || '';
    const selected = sheets.find((sheet: any) => sheet.name === active);
    setDeliverySheets(sheets.map((sheet: any) => ({ name: String(sheet.name), rows: Array.isArray(sheet.rows) ? sheet.rows.length : 0 })));
    setDeliverySheet(active);
    const nextRows = selected ? selected.rows : (Array.isArray(payload?.rows) ? payload.rows : []);
    if (nextRows.length) { setRows(nextRows.map(normalizeRow)); setDeliveryTotal(nextRows.length); }
    setFilters({});
    setSelectedRows([]);
  };

  useEffect(() => { setTab(initialTab); }, [initialTab]);
  useEffect(() => {
    if (!isDesktop() || !window.rubaDesktop?.getDeliveryCsvStatus) return;
    let cancelled = false;
    const loadStatus = async () => { try { const result = await window.rubaDesktop?.getDeliveryCsvStatus?.(); if (!cancelled && result) setCsvStatus(result); } catch {} };
    void loadStatus();
    return () => { cancelled = true; };
  }, []);
  useEffect(() => {
    if (!isDesktop() || !window.rubaDesktop?.listDeliveryPlans) return;
    let cancelled = false;
    window.rubaDesktop.listDeliveryPlans('delivery_csv_source').then((nextPlans) => {
      if (cancelled) return;
      const latest = (nextPlans || [])[0];
      if (!latest) return;
      const payload = typeof latest.payload_json === 'string' ? JSON.parse(latest.payload_json || '{}') : (latest.payload || {});
      setSelectedProjectId('delivery_csv_source');
      setPlans(nextPlans || []);
      setPlanId(latest.id);
      setPlanName(latest.plan_name || 'Delivery plan source');
      applyDeliveryPayload(payload);
      void loadDeliveryRows(latest.id, payload?.activeSheet || '', 0, '');
    }).catch(() => { if (!cancelled) setMessage('Le Delivery Plan a été trouvé mais ses lignes ne peuvent pas être affichées.'); });
    return () => { cancelled = true; };
  }, []);
  useEffect(() => {
    let cancelled = false;
    if (!selectedProjectId || !isDesktop() || !window.rubaDesktop?.listDeliveryPlans) {
      setPlans([]); setPlanId(''); setPlanName(''); setRows([normalizeRow({})]);
      return;
    }
    window.rubaDesktop.listDeliveryPlans(selectedProjectId).then((nextPlans) => {
      if (cancelled) return;
      setPlans(nextPlans || []);
      const latest = (nextPlans || [])[0];
      if (!latest) { setPlanId(''); setRows([normalizeRow({})]); return; }
      const payload = typeof latest.payload_json === 'string' ? JSON.parse(latest.payload_json || '{}') : (latest.payload || {});
      setPlanId(latest.id); setPlanName(latest.plan_name || '');
      applyDeliveryPayload(payload, deliverySheet);
      void loadDeliveryRows(latest.id, deliverySheet || payload?.activeSheet || '', 0, deliverySearch);
    }).catch(() => { if (!cancelled) setMessage('Impossible de recharger le Delivery Plan depuis SQLite.'); });
    return () => { cancelled = true; };
  }, [selectedProjectId]);
  const loadDeliveryRows = async (planId: string, sheetName = deliverySheet, page = 0, searchValue = deliverySearch) => {
    if (!window.rubaDesktop?.listDeliveryRows) return;
    const result = await window.rubaDesktop.listDeliveryRows({ planId, sheetName, page, pageSize: deliveryPageSize, search: searchValue });
    setRows((result.rows || []).map(normalizeRow)); setDeliveryTotal(result.total || 0); setDeliveryPage(result.page || 0); setSelectedRows([]);
  };

  const changeDeliverySheet = (sheetName: string) => {
    if (!isDesktop() || !window.rubaDesktop?.listDeliveryPlans || !selectedProjectId) return;
    setDeliverySheet(sheetName);
    const latest = plans[0];
    if (!latest) return;
    const payload = typeof latest.payload_json === 'string' ? JSON.parse(latest.payload_json || '{}') : (latest.payload || {});
    applyDeliveryPayload(payload, sheetName);
    void loadDeliveryRows(latest.id, sheetName, 0, deliverySearch);
  };
  const refresh = async (query = deferredSearch) => {
    if (!isDesktop()) return;
    const api = window.rubaDesktop!;
    const projectFilters = { search: query, customer: dashboardCustomer, status: dashboardStatus, archived: dashboardArchived === 'all' ? undefined : dashboardArchived === 'archived' };
    const [nextSummary, nextProjects, nextFiles, root] = await Promise.all([api.dbSummary(), api.listProjects(projectFilters), api.listFiles({ search: query }), api.getStorageRoot()]);
    setSummary(nextSummary); setProjects(nextProjects); setFiles(nextFiles); setStorageRoot(root);
    if (!selectedProjectId && nextProjects[0]) setSelectedProjectId(nextProjects[0].id);
  };
  useEffect(() => { refresh().catch(() => setMessage('Le centre local sera disponible dans la version desktop.')); }, [deferredSearch, dashboardCustomer, dashboardStatus, dashboardArchived]);
  useEffect(() => { if (selectedProjectId && planId && window.rubaDesktop?.listDeliveryRows) void loadDeliveryRows(planId, deliverySheet, 0, deferredDeliverySearch); }, [deferredDeliverySearch, planId, deliverySheet]);
  useEffect(() => {
    const meta = projectPayload?.meta || {};
    if (!window.rubaDesktop?.getDeliveryBreakdown || !meta.order) { setBreakdownByColor([]); return; }
    window.rubaDesktop.getDeliveryBreakdown({ orderNumber: String(meta.order), customer: String(meta.customer || ''), po: String(meta.po || '') }).then(setBreakdownByColor).catch(() => setBreakdownByColor([]));
  }, [projectPayload?.meta?.order, projectPayload?.meta?.customer, projectPayload?.meta?.po]);
  useEffect(() => { document.body.style.zoom = `${zoom / 100}`; document.documentElement.style.setProperty('--ruba-accent', accent); return () => { document.body.style.zoom = '1'; }; }, [zoom, accent]);

  const applyZoom = (value: number) => { const next = Math.max(80, Math.min(125, value)); setZoom(next); localStorage.setItem('ruba_ui_zoom', String(next)); };
  const saveAccent = (value: string) => { setAccent(value); localStorage.setItem('ruba_accent', value); document.documentElement.style.setProperty('--ruba-accent', value); };
  const createProject = async () => { if (!isDesktop() || !projectName.trim()) return; const saved = await window.rubaDesktop!.saveProject({ name: projectName.trim(), customer, status: 'draft', payload: projectPayload || {} }); setProjectName(''); setCustomer(''); setSelectedProjectId(saved.id); setMessage('Travail enregistré dans SQLite.'); await refresh(); };
  const syncCsv = async () => { if (!isDesktop() || !window.rubaDesktop?.syncDeliveryCsv) return; try { const result = await window.rubaDesktop.syncDeliveryCsv(); setCsvStatus(result); if (result.found) { setSelectedProjectId('delivery_csv_source'); const nextPlans = await window.rubaDesktop.listDeliveryPlans?.('delivery_csv_source') || []; const latest = nextPlans[0]; if (latest) { const payload = typeof latest.payload_json === 'string' ? JSON.parse(latest.payload_json || '{}') : (latest.payload || {}); setPlans(nextPlans); setPlanId(latest.id); setPlanName(latest.plan_name || 'Delivery plan source'); applyDeliveryPayload(payload); await loadDeliveryRows(latest.id, payload?.activeSheet || '', 0, ''); } setMessage(`${result.source?.toLowerCase().endsWith('.xlsx') ? 'Delivery plan.xlsx' : 'Delivery plan.csv'} synchronisé et affiché : ${result.rows || 0} ligne(s).`); } else setMessage(result.error ? `Synchronisation refusée : ${result.error}` : 'Aucun fichier Delivery Plan trouvé dans les emplacements configurés.'); } catch (error) { setMessage(`La synchronisation du Delivery Plan a échoué : ${error instanceof Error ? error.message : 'erreur inconnue'}`); } };
  const chooseRoot = async () => { if (!isDesktop()) return; const next = await window.rubaDesktop!.chooseStorageRoot(); if (next) { setStorageRoot(next); setMessage('Dossier de stockage modifié.'); } };
  const capture = async () => { if (!isDesktop()) return; const result = await window.rubaDesktop!.captureWindow(); if (!result.canceled) setMessage(`Capture enregistrée : ${result.filePath}`); };
  const loadProject = async (project: any) => { const full = await window.rubaDesktop?.getProject(project.id); if (full) await onLoadProject?.(full); setMessage(`Projet chargé : ${project.name}`); };
  const archiveProject = async (project: any) => { if (!window.confirm(`Archiver le projet « ${project.name} » ?`)) return; await window.rubaDesktop?.archiveProject(project.id); setMessage(`Projet archivé : ${project.name}`); await refresh(); };
  const restoreProject = async (project: any) => { await window.rubaDesktop?.restoreProject(project.id); setMessage(`Projet restauré : ${project.name}`); await refresh(); };
  const showVersions = async (project: any) => { setSelectedVersionProject(project); setVersions(await window.rubaDesktop?.listProjectVersions(project.id) || []); };
  const updateRow = (id: string, key: string, value: string) => setRows(previous => previous.map(row => { if (row.id !== id) return row; const next = { ...row, [key]: numericKeys.has(key) ? Number(value || 0) : value } as DeliveryRow; next.cbm = Number(((Number(next.l) || 0) * (Number(next.h) || 0) * (Number(next.w) || 0)) / 1000000).toFixed(6) as unknown as number; return next; }));
  const filteredRows = useMemo(() => rows.filter(row => {
    const matchesGlobal = !deferredDeliverySearch || Object.values(row).some(value => String(value ?? '').toLowerCase().includes(deferredDeliverySearch.toLowerCase()));
    const matchesColumns = Object.entries(filters).every(([key, value]) => !value || String(row[key] ?? '').toLowerCase().includes(String(value).toLowerCase()));
    return matchesGlobal && matchesColumns;
  }), [rows, filters, deferredDeliverySearch]);
  const totalCbm = rows.reduce((sum, row) => sum + Number(row.cbm || 0), 0);
  const activeProject = projects.find(project => project.id === selectedProjectId) || null;
  const activeMeta = projectPayload?.meta || {};
  const selectedProjectColors = Array.isArray(projectPayload?.colors) ? projectPayload.colors.map((color: any) => String(color.nom || color.name || '').trim()).filter(Boolean) : [];
  const breakdownPoTotal = breakdownByColor.reduce((sum, item) => sum + Number(item.poQty || 0), 0);
  const breakdownPlTotal = Array.isArray(projectPayload?.colors) ? projectPayload.colors.reduce((sum: number, color: any) => sum + Object.values(color.sizes || {}).reduce<number>((inner, size: any) => inner + Number(size?.qtyTot || size?.qty || 0), 0), 0) : 0;
  const breakdownPercent = breakdownPoTotal > 0 ? ((breakdownPlTotal - breakdownPoTotal) / breakdownPoTotal) * 100 : 0;
  const breakdownBarWidth = Math.min(100, Math.abs(breakdownPercent));
  const breakdownByColorView = breakdownByColor.map(item => {
    const model = Array.isArray(projectPayload?.colors) ? projectPayload.colors.find((color: any) => String(color.nom || color.name || '').trim().toLowerCase() === item.color.toLowerCase()) : null;
    const plQty = model ? Object.values(model.sizes || {}).reduce<number>((sum, size: any) => sum + Number(size?.qtyTot || size?.qty || 0), 0) : 0;
    const poQty = Number(item.poQty || 0);
    return { ...item, plQty, poQty, percent: poQty > 0 ? ((plQty - poQty) / poQty) * 100 : 0 };
  });
  const qualityChecks = useMemo(() => {
    const order = String(activeMeta.order || activeProject?.order_number || '').trim();
    const customer = String(activeMeta.customer || activeProject?.customer || '').trim();
    const po = String(activeMeta.po || activeProject?.po_number || '').trim();
    const destination = String(activeMeta.destination || '').trim();
    const dimensionsReady = Array.isArray(projectPayload?.colors) && projectPayload.colors.length > 0 && projectPayload.colors.every((color: any) => Object.values(color.sizes || {}).every((size: any) => Number(size?.dimL || size?.diml || 0) > 0 && Number(size?.dimH || 0) > 0 && Number(size?.dimW || size?.dimw || 0) > 0));
    const quantitiesBalanced = breakdownPoTotal > 0 && Math.abs(breakdownPercent) < 0.0001;
    const cartons = projectPayload?.cartons || projectPayload?.packingList?.cartons || projectPayload?.results || [];
    return [
      { key: 'references', level: order && customer && po && destination ? 'ok' : 'error', label: 'Références complètes', detail: order && customer && po && destination ? 'Order #, client, PO et destination sont renseignés.' : 'Order #, client, PO ou destination est manquant.', tab: 'dashboard' as CenterTab },
      { key: 'delivery', level: order && breakdownByColor.length ? 'ok' : order ? 'warning' : 'error', label: 'Delivery Plan SQLite', detail: breakdownByColor.length ? `${breakdownByColor.length} couleur(s) et PO QTY disponibles.` : 'Aucune ligne correspondante trouvée pour cette combinaison.', tab: 'delivery' as CenterTab },
      { key: 'colors', level: selectedProjectColors.length && breakdownByColor.length ? 'ok' : 'warning', label: 'Couleurs du projet', detail: selectedProjectColors.length ? `${selectedProjectColors.length} couleur(s) dans le projet.` : 'Aucune couleur n’est encore sélectionnée.', tab: 'dashboard' as CenterTab },
      { key: 'quantities', level: breakdownPoTotal <= 0 ? 'warning' : quantitiesBalanced ? 'ok' : 'warning', label: 'Quantités PL / PO QTY', detail: breakdownPoTotal > 0 ? `Écart global : ${breakdownPercent > 0 ? '+' : ''}${breakdownPercent.toFixed(1)} %.` : 'PO QTY indisponible pour le calcul.', tab: 'dashboard' as CenterTab },
      { key: 'dimensions', level: dimensionsReady ? 'ok' : 'warning', label: 'Dimensions carton', detail: dimensionsReady ? 'L, W et H sont disponibles pour les tailles du projet.' : 'Certaines dimensions L/W/H sont absentes ou incomplètes.', tab: 'dashboard' as CenterTab },
      { key: 'cartons', level: Array.isArray(cartons) && cartons.length ? 'ok' : 'warning', label: 'Packing List / cartons', detail: Array.isArray(cartons) && cartons.length ? `${cartons.length} carton(s) détecté(s).` : 'Aucun carton final détecté.', tab: 'dashboard' as CenterTab }
    ] as Array<{ key: string; level: 'ok' | 'warning' | 'error'; label: string; detail: string; tab: CenterTab }>;
  }, [activeMeta.order, activeMeta.customer, activeMeta.po, activeMeta.destination, activeProject?.order_number, activeProject?.po_number, activeProject?.customer, projectPayload, breakdownByColor, breakdownPoTotal, breakdownPercent, selectedProjectColors.length]);
  const qualityErrors = qualityChecks.filter(check => check.level === 'error').length;
  const qualityWarnings = qualityChecks.filter(check => check.level === 'warning').length;
  const qualityScore = Math.round(((qualityChecks.length - qualityErrors - qualityWarnings * 0.5) / qualityChecks.length) * 100);
  const deleteSelectedRows = async () => { if (!selectedRows.length) return; const ids = [...selectedRows]; setRows(previous => previous.filter(row => !ids.includes(row.id))); setSelectedRows([]); if (window.rubaDesktop?.deleteDeliveryRows) { await window.rubaDesktop.deleteDeliveryRows({ ids }); setMessage(`${ids.length} ligne(s) supprimée(s) de SQLite.`); if (planId) await loadDeliveryRows(planId, deliverySheet, deliveryPage, deferredDeliverySearch); } };
  const openDeliveryManager = async () => { if (!planId || !window.rubaDesktop?.listDeliveryRows) { setMessage('Aucun Delivery Plan SQLite sélectionné.'); return; } setShowDeliveryManager(true); setManagerPage(0); setManagerSelected([]); const result = await window.rubaDesktop.listDeliveryRows({ planId, sheetName: deliverySheet, page: 0, pageSize: 250, search: '' }); setManagerRows((result.rows || []).map(normalizeRow)); setManagerTotal(result.total || 0); };
  const refreshDeliveryManager = async (page = managerPage, search = managerSearch) => { if (!planId || !window.rubaDesktop?.listDeliveryRows) return; const result = await window.rubaDesktop.listDeliveryRows({ planId, sheetName: deliverySheet, page, pageSize: 250, search }); setManagerRows((result.rows || []).map(normalizeRow)); setManagerTotal(result.total || 0); setManagerSelected([]); };
  const deleteManagerRows = async () => { if (!managerSelected.length || !window.rubaDesktop?.deleteDeliveryRows) return; if (!window.confirm(`Supprimer ${managerSelected.length} ligne(s) du Delivery Plan ?`)) return; const count = managerSelected.length; await window.rubaDesktop.deleteDeliveryRows({ ids: managerSelected }); setMessage(`${count} ligne(s) supprimée(s) du Delivery Plan.`); await refreshDeliveryManager(managerPage, managerSearch); if (planId) await loadDeliveryRows(planId, deliverySheet, deliveryPage, deferredDeliverySearch); };
  const clearDeliveryDatabase = async () => { if (!planId || !window.rubaDesktop?.clearDeliveryRows) return; if (!window.confirm('Vider définitivement toutes les lignes du Delivery Plan dans SQLite ?')) return; await window.rubaDesktop.clearDeliveryRows(planId); setManagerRows([]); setManagerTotal(0); setManagerSelected([]); setRows([normalizeRow({})]); setDeliveryTotal(0); setMessage('Toutes les lignes du Delivery Plan ont été supprimées de SQLite.'); };
  const savePlan = async () => { if (!isDesktop() || !selectedProjectId || !planName.trim()) { setMessage('Choisissez un travail et renseignez le nom du Delivery Plan.'); return; } const cleanRows = rows.filter(row => Object.values(row).some(value => String(value ?? '').trim() && value !== 0)); const plan = await window.rubaDesktop!.saveDeliveryPlan({ id: planId || undefined, projectId: selectedProjectId, planName, payload: { rows: cleanRows, paged: Boolean(planId && window.rubaDesktop?.listDeliveryRows) } }); setPlanId(plan.id); const refreshed = await window.rubaDesktop!.listDeliveryPlans(selectedProjectId); setPlans(refreshed || []); setMessage(`${cleanRows.length} ligne(s) enregistrée(s) dans SQLite.`); await refresh(); };
  const handlePaste = (event: ClipboardEvent<HTMLDivElement>) => {
    const text = event.clipboardData.getData('text/plain'); if (!text.includes('\t') && !text.includes('\n')) return;
    event.preventDefault(); const matrix = text.trim().split(/\r?\n/).map(line => line.split('\t'));
    const first = matrix[0].map(normalizeHeader); const hasHeaders = first.some(header => Boolean(headerAliases[header]));
    const keys = hasHeaders ? first.map(header => headerAliases[header] || '') : deliveryColumns.map(column => column.key);
    const data = (hasHeaders ? matrix.slice(1) : matrix).filter(line => line.some(cell => String(cell).trim()));
    setRows(data.map(line => normalizeRow(Object.fromEntries(line.map((value, index) => keys[index] ? [keys[index], value] : []).filter(Boolean)))));
    setFilters({}); setSelectedRows([]); setMessage(`${data.length} ligne(s) collée(s) depuis Excel.`);
  };
  const toggleSelected = (id: string) => setSelectedRows(previous => previous.includes(id) ? previous.filter(item => item !== id) : [...previous, id]);
  const tabs = useMemo(() => [['dashboard', 'Dashboard'], ['projects', 'Travaux'], ['files', 'Fichiers'], ['delivery', 'Delivery Plan'], ['quality', 'Contrôle qualité'], ['settings', 'Paramètres']] as const, []);

  return <section className="flex-1 min-h-0 overflow-auto rounded-2xl border border-slate-200 bg-white shadow-sm" style={{ ['--ruba-accent' as any]: accent }}>
    <div className="sticky top-0 z-20 flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 bg-white/95 px-5 py-4 backdrop-blur"><div><p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">Ruba Industrial Workspace</p><h2 className="text-xl font-black text-slate-900">Centre de pilotage</h2></div><div className="flex flex-wrap items-center gap-2"><button onClick={() => applyZoom(zoom - 5)} className="rounded-lg border border-slate-200 bg-white p-2 text-slate-700 hover:bg-slate-50"><ZoomOut size={16}/></button><span className="min-w-12 text-center text-xs font-bold text-slate-600">{zoom}%</span><button onClick={() => applyZoom(zoom + 5)} className="rounded-lg border border-slate-200 bg-white p-2 text-slate-700 hover:bg-slate-50"><ZoomIn size={16}/></button><button onClick={capture} className="flex items-center gap-2 rounded-lg bg-slate-900 px-3 py-2 text-xs font-bold text-white"><Camera size={15}/> Capture</button><button onClick={onBack} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-bold text-slate-700">Retour au colisage</button></div></div>
    {showTabs && <div className="flex gap-2 overflow-x-auto border-b border-slate-100 px-5 py-3">{tabs.map(([id, label]) => <button key={id} onClick={() => setTab(id)} className={`rounded-xl px-3 py-2 text-xs font-bold ${tab === id ? 'text-white shadow-sm' : 'bg-slate-50 text-slate-600'}`} style={tab === id ? { backgroundColor: accent } : undefined}>{label}</button>)}</div>}
    <aside data-context-card="active" className="mx-5 mt-4 w-auto rounded-2xl border border-indigo-200 bg-gradient-to-br from-indigo-50 via-white to-teal-50 p-4 text-slate-800 shadow-sm xl:fixed xl:right-5 xl:top-24 xl:z-30 xl:mx-0 xl:w-72">
      <div className="flex items-center justify-between"><p className="text-[10px] font-black uppercase tracking-[0.16em] text-indigo-700">Contexte actif</p><span className="rounded-full bg-emerald-100 px-2 py-1 text-[9px] font-black uppercase text-emerald-700">{activeProject?.archived ? 'Archivé' : activeProject ? (activeProject.status || 'Actif') : 'Aucun projet'}</span></div>
      <p className="mt-2 truncate text-sm font-black text-slate-900">{activeProject?.name || 'Aucun projet sélectionné'}</p>
      <div className="mt-3 space-y-1.5 text-[11px]"><div className="flex justify-between gap-2"><span className="text-slate-500">Order #</span><b className="max-w-[170px] truncate text-right font-mono">{activeMeta.order || activeProject?.order_number || '—'}</b></div><div className="flex justify-between gap-2"><span className="text-slate-500">PO</span><b className="max-w-[170px] truncate text-right font-mono">{activeMeta.po || activeProject?.po_number || '—'}</b></div><div className="flex justify-between gap-2"><span className="text-slate-500">Client</span><b className="max-w-[170px] truncate text-right">{activeMeta.customer || activeProject?.customer || '—'}</b></div><div className="flex justify-between gap-2"><span className="text-slate-500">Quantité PL</span><b className="text-right">{breakdownPlTotal.toLocaleString('fr-FR')} pcs</b></div></div>
      <div className="mt-4 border-t border-indigo-200 pt-3"><div className="flex items-center justify-between"><span className="text-[10px] font-black uppercase text-indigo-700">Écart PL vs PO QTY</span><b className={`font-mono ${breakdownPercent < 0 ? 'text-amber-700' : breakdownPercent > 0 ? 'text-rose-700' : 'text-emerald-700'}`}>{breakdownPercent > 0 ? '+' : ''}{breakdownPercent.toFixed(1)}%</b></div><div className="mt-2 h-2 w-full rounded-full bg-indigo-100"><div className={`h-2 rounded-full ${breakdownPercent < 0 ? 'bg-amber-500' : breakdownPercent > 0 ? 'bg-rose-500' : 'bg-emerald-500'}`} style={{ width: `${breakdownBarWidth}%` }} /></div><p className="mt-1 text-[10px] text-slate-500">{breakdownPlTotal.toLocaleString('fr-FR')} / {breakdownPoTotal.toLocaleString('fr-FR')} pcs</p>{breakdownByColorView.length > 0 && <div className="mt-3 space-y-2">{breakdownByColorView.map(item => <div key={item.color}><div className="flex justify-between gap-2 text-[10px]"><span className="max-w-[120px] truncate font-semibold">{item.color}</span><span className={`font-mono ${item.percent < 0 ? 'text-amber-700' : item.percent > 0 ? 'text-rose-700' : 'text-emerald-700'}`}>{item.percent > 0 ? '+' : ''}{item.percent.toFixed(1)}%</span></div><div className="mt-1 h-1.5 w-full rounded-full bg-slate-200"><div className={`h-1.5 rounded-full ${item.percent < 0 ? 'bg-amber-500' : item.percent > 0 ? 'bg-rose-500' : 'bg-emerald-500'}`} style={{ width: `${Math.min(100, Math.abs(item.percent))}%` }} /></div><p className="mt-0.5 text-[9px] text-slate-500">PL {item.plQty.toLocaleString('fr-FR')} / PO {item.poQty.toLocaleString('fr-FR')}</p></div>)}</div>}</div>
    </aside>
    {message && <div className="mx-5 mt-4 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-800">{message}</div>}
    {tab === 'quality' && <div className="space-y-5 p-5"><div className="rounded-2xl border border-indigo-200 bg-gradient-to-r from-indigo-50 via-white to-teal-50 p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-700">Contrôle qualité du projet</p><h3 className="mt-1 text-2xl font-black text-slate-900">Prêt pour la Packing List ?</h3><p className="mt-1 max-w-2xl text-sm text-slate-600">Ruba vérifie les références, les données SQLite, les quantités, les dimensions et les cartons avant l’export.</p></div><div className="text-right"><p className="text-4xl font-black text-indigo-700">{Math.max(0, qualityScore)}%</p><p className="text-[10px] font-bold uppercase text-slate-500">score de complétude</p></div></div><div className="mt-4 flex flex-wrap gap-2 text-xs font-bold"><span className="rounded-full bg-red-100 px-3 py-1.5 text-red-700">{qualityErrors} erreur(s)</span><span className="rounded-full bg-amber-100 px-3 py-1.5 text-amber-700">{qualityWarnings} avertissement(s)</span><span className="rounded-full bg-emerald-100 px-3 py-1.5 text-emerald-700">{qualityChecks.length - qualityErrors - qualityWarnings} conforme(s)</span></div></div><div className="grid gap-3 md:grid-cols-2">{qualityChecks.map(check => <div key={check.key} className={`rounded-xl border p-4 ${check.level === 'ok' ? 'border-emerald-200 bg-emerald-50/60' : check.level === 'warning' ? 'border-amber-200 bg-amber-50/60' : 'border-red-200 bg-red-50/60'}`}><div className="flex items-start gap-3">{check.level === 'ok' ? <CheckCircle2 className="mt-0.5 shrink-0 text-emerald-600" size={20}/> : check.level === 'warning' ? <AlertTriangle className="mt-0.5 shrink-0 text-amber-600" size={20}/> : <XCircle className="mt-0.5 shrink-0 text-red-600" size={20}/>}<div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><h4 className="font-black text-slate-900">{check.label}</h4><span className={`text-[10px] font-black uppercase ${check.level === 'ok' ? 'text-emerald-700' : check.level === 'warning' ? 'text-amber-700' : 'text-red-700'}`}>{check.level === 'ok' ? 'Conforme' : check.level === 'warning' ? 'À vérifier' : 'Erreur'}</span></div><p className="mt-1 text-xs text-slate-600">{check.detail}</p>{check.level !== 'ok' && <button onClick={() => setTab(check.tab)} className="mt-3 rounded-lg bg-white px-3 py-1.5 text-[10px] font-black text-indigo-700 shadow-sm ring-1 ring-indigo-200">Corriger</button>}</div></div></div>)}</div><div className="rounded-xl border border-slate-200 bg-slate-50 p-4 text-xs text-slate-600"><div className="flex items-center gap-2 font-bold text-slate-800"><ClipboardCheck size={16} className="text-indigo-600"/> Règle de validation</div><p className="mt-1">Une erreur doit être corrigée avant de considérer le projet prêt. Un avertissement peut être examiné puis enregistré avec le projet.</p></div></div>}
    {tab === 'dashboard' && <div className="space-y-5 p-5">
      <div className="rounded-2xl border border-violet-200 bg-gradient-to-r from-violet-50 via-white to-indigo-50 p-4 shadow-sm">
        <div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-[10px] font-black uppercase tracking-[0.2em] text-violet-700">Accueil opérationnel</p><h3 className="mt-1 text-lg font-black text-slate-900">Accès direct aux modules Ruba</h3><p className="mt-1 text-xs text-slate-600">Ouvrez un espace de travail sans repasser par les rubans secondaires.</p></div><span className="rounded-full bg-violet-100 px-3 py-1.5 text-[10px] font-black uppercase text-violet-800">v2.9.0</span></div>
        <div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-5">{[['projects','Travaux','Gérer les projets'],['delivery','Delivery Plan','Consulter les lignes'],['files','Fichiers','Importer et exporter'],['quality','Contrôle qualité','Vérifier le projet'],['settings','Paramètres','Configurer Ruba']].map(([id,label,description]) => <button key={id} type="button" onClick={() => setTab(id as CenterTab)} className="group rounded-xl border border-slate-200 bg-white px-3 py-3 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-violet-300 hover:bg-violet-50"><span className="block text-xs font-black text-slate-900 group-hover:text-violet-800">{label}</span><span className="mt-1 block text-[10px] leading-4 text-slate-500">{description}</span></button>)}</div>
      </div>
      <div className="grid gap-4 md:grid-cols-5">{[['Projets actifs', summary.projects], ['Packing Lists', summary.packingLists], ['Fichiers', summary.files], ['Delivery Plans', summary.deliveryPlans], ['Lignes breakdown', summary.breakdownRows]].map(([label, value]: any) => <div key={label} className="rounded-2xl border border-slate-200 bg-gradient-to-br from-white to-slate-50 p-5 shadow-sm"><span className="inline-block h-3 w-3 rounded-full" style={{ backgroundColor: accent }} /><p className="mt-4 text-xs font-bold uppercase tracking-wider text-slate-500">{label}</p><p className="mt-1 text-3xl font-black text-slate-900">{value}</p></div>)}</div>
      <div className="rounded-2xl border border-slate-200 bg-slate-50 p-4"><div className="mb-3 flex flex-wrap items-center gap-2"><div className="flex min-w-[260px] flex-1 items-center gap-2 rounded-lg border bg-white px-3 py-2"><Search size={15} className="text-slate-400"/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Rechercher projet, client, commande, PO..." className="w-full text-sm outline-none"/></div><input value={dashboardCustomer} onChange={e => setDashboardCustomer(e.target.value)} placeholder="Client" className="rounded-lg border bg-white px-3 py-2 text-sm"/><select value={dashboardStatus} onChange={e => setDashboardStatus(e.target.value)} className="rounded-lg border bg-white px-3 py-2 text-sm"><option value="">Tous les statuts</option><option value="draft">Brouillon</option><option value="active">Actif</option><option value="completed">Terminé</option><option value="archived">Archivé</option></select><select value={dashboardArchived} onChange={e => setDashboardArchived(e.target.value as any)} className="rounded-lg border bg-white px-3 py-2 text-sm"><option value="active">Actifs uniquement</option><option value="archived">Archivés uniquement</option><option value="all">Tous</option></select><button onClick={() => refresh()} className="rounded-lg border bg-white p-2"><RefreshCw size={16}/></button></div><p className="text-xs font-bold text-slate-500">{projects.length} projet(s) trouvé(s)</p></div>
      <div className="overflow-auto rounded-xl border border-slate-200"><table className="w-full min-w-[980px] text-left text-sm"><thead className="bg-slate-900 text-xs uppercase text-white"><tr><th className="px-4 py-3">Projet</th><th className="px-4 py-3">Client</th><th className="px-4 py-3">Commande / PO</th><th className="px-4 py-3">Statut</th><th className="px-4 py-3">Mise à jour</th><th className="px-4 py-3 text-right">Actions</th></tr></thead><tbody>{projects.map(project => <tr key={project.id} className="border-t border-slate-100 hover:bg-teal-50/30"><td className="px-4 py-3 font-bold">{project.name}</td><td className="px-4 py-3">{project.customer || '—'}</td><td className="px-4 py-3">{project.order_number || '—'} <span className="text-slate-400">/ {project.po_number || '—'}</span></td><td className="px-4 py-3"><span className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase ${project.archived ? 'bg-slate-200 text-slate-600' : 'bg-emerald-100 text-emerald-700'}`}>{project.archived ? 'Archivé' : project.status}</span></td><td className="px-4 py-3 text-xs text-slate-500">{new Date(project.updated_at).toLocaleString('fr-FR')}</td><td className="px-4 py-3"><div className="flex justify-end gap-1"><button onClick={() => loadProject(project)} className="rounded-lg border border-teal-200 px-2 py-1.5 text-[10px] font-bold text-teal-700">Ouvrir</button><button onClick={() => showVersions(project)} className="rounded-lg border border-violet-200 p-1.5 text-violet-700" title="Versions"><History size={14}/></button>{project.archived ? <button onClick={() => restoreProject(project)} className="rounded-lg border border-blue-200 p-1.5 text-blue-700" title="Restaurer"><RotateCcw size={14}/></button> : <button onClick={() => archiveProject(project)} className="rounded-lg border border-amber-200 p-1.5 text-amber-700" title="Archiver"><Archive size={14}/></button>}</div></td></tr>)}{projects.length === 0 && <tr><td colSpan={6} className="p-10 text-center text-sm text-slate-500">Aucun projet ne correspond aux filtres.</td></tr>}</tbody></table></div>
      {selectedVersionProject && <div className="rounded-2xl border border-violet-200 bg-violet-50 p-4"><div className="flex items-center justify-between"><div><h3 className="font-black text-violet-900">Versions — {selectedVersionProject.name}</h3><p className="text-xs text-violet-700">{versions.length} version(s) sauvegardée(s)</p></div><button onClick={() => setSelectedVersionProject(null)} className="rounded-lg border border-violet-200 bg-white px-3 py-1 text-xs font-bold">Fermer</button></div><div className="mt-3 space-y-2">{versions.map(version => <div key={version.id} className="flex items-center justify-between rounded-lg border border-violet-100 bg-white px-3 py-2"><span className="text-xs font-bold">Version {version.version_number} — {new Date(version.created_at).toLocaleString('fr-FR')}</span><button onClick={async () => { if (!window.confirm('Restaurer cette version ?')) return; await window.rubaDesktop?.restoreProjectVersion(version.id); setSelectedVersionProject(null); await refresh(); }} className="rounded-lg bg-violet-700 px-3 py-1 text-[10px] font-bold text-white">Restaurer</button></div>)}{versions.length === 0 && <p className="text-xs text-violet-700">Aucune version précédente pour ce projet.</p>}</div></div>}
    </div>}
    {tab === 'projects' && <div className="space-y-4 p-5"><div className="flex flex-wrap gap-2"><input value={projectName} onChange={e => setProjectName(e.target.value)} placeholder="Nom du travail" className="rounded-lg border px-3 py-2 text-sm"/><input value={customer} onChange={e => setCustomer(e.target.value)} placeholder="Client" className="rounded-lg border px-3 py-2 text-sm"/><button onClick={createProject} className="flex items-center gap-2 rounded-lg px-4 py-2 text-xs font-bold text-white" style={{ backgroundColor: accent }}><Plus size={14}/> Nouveau travail</button></div><div className="overflow-auto rounded-xl border"><table className="w-full text-left text-sm"><thead className="bg-slate-900 text-xs uppercase text-white"><tr><th className="px-4 py-3">Nom</th><th className="px-4 py-3">Client</th><th className="px-4 py-3">Statut</th><th className="px-4 py-3">Dernière mise à jour</th><th className="px-4 py-3 text-right">Actions</th></tr></thead><tbody>{projects.map(p => <tr key={p.id} className="border-t"><td className="px-4 py-3 font-bold">{p.name}</td><td className="px-4 py-3">{p.customer}</td><td className="px-4 py-3">{p.status}</td><td className="px-4 py-3 text-slate-500">{new Date(p.updated_at).toLocaleString()}</td><td className="px-4 py-3"><div className="flex justify-end gap-3"><button onClick={async () => { const full = await window.rubaDesktop?.getProject(p.id); if (full) await onLoadProject?.(full); setMessage(`Projet chargé : ${p.name}`); }} className="rounded-lg border border-teal-200 px-3 py-1.5 text-xs font-bold text-teal-700">Charger</button><button onClick={async () => { if (!window.confirm(`Supprimer le projet « ${p.name} » ?`)) return; await window.rubaDesktop?.deleteProject(p.id); refresh(); }} className="text-rose-600"><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div></div>}
    {tab === 'files' && <div className="space-y-4 p-5"><div className="flex items-center gap-2"><div className="flex flex-1 items-center gap-2 rounded-lg border px-3 py-2"><Search size={15} className="text-slate-400"/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Filtrer les fichiers et travaux" className="w-full text-sm outline-none"/></div><button onClick={refresh} className="rounded-lg border p-2"><RefreshCw size={16}/></button><button onClick={async () => { const imported = await window.rubaDesktop?.importFile({ fileKind: 'excel' }); if (imported) { setMessage(`Fichier importé : ${imported.name}`); await refresh(); } }} className="flex items-center gap-2 rounded-lg px-3 py-2 text-xs font-bold text-white" style={{ backgroundColor: accent }}><Upload size={14}/> Importer Excel</button></div><div className="overflow-auto rounded-xl border"><table className="w-full text-left text-sm"><thead className="bg-slate-900 text-xs uppercase text-white"><tr><th className="px-4 py-3">Fichier</th><th className="px-4 py-3">Type</th><th className="px-4 py-3">Travail</th><th className="px-4 py-3">Chemin</th></tr></thead><tbody>{files.map(f => <tr key={f.id} className="border-t"><td className="px-4 py-3 font-bold">{f.name}</td><td className="px-4 py-3">{f.file_kind}</td><td className="px-4 py-3">{f.project_name || '—'}</td><td className="max-w-md truncate px-4 py-3 text-slate-500">{f.stored_path}</td></tr>)}</tbody></table></div></div>}
    {tab === 'delivery' && <div className="space-y-4 p-5"><div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-blue-200 bg-blue-50 p-4"><div className="min-w-0"><p className="text-xs font-black uppercase tracking-wide text-blue-900">Delivery Plan — base SQLite principale</p><p className="mt-1 truncate text-xs text-blue-800">{deliveryTotal ? `${deliveryTotal} ligne(s) stockée(s) dans SQLite` : 'Ajoutez ou collez vos lignes directement dans la grille. Le fichier Delivery plan.csv reste disponible uniquement pour un import manuel.'}</p></div><div className="flex items-center gap-2"><button onClick={syncCsv} className="flex shrink-0 items-center gap-2 rounded-lg bg-blue-700 px-4 py-2 text-xs font-bold text-white hover:bg-blue-800"><Upload size={14}/> Importer CSV</button><select value={deliverySheet} onChange={e => changeDeliverySheet(e.target.value)} disabled={!deliverySheets.length} className="rounded-lg border border-blue-200 bg-white px-3 py-2 text-xs font-bold text-blue-900"><option value="">Feuille actuelle</option>{deliverySheets.map(sheet => <option key={sheet.name} value={sheet.name}>{sheet.name} ({sheet.rows} lignes)</option>)}</select></div></div><div className="flex flex-wrap items-center gap-2 rounded-xl border border-slate-200 bg-slate-50 p-4"><select value={selectedProjectId} onChange={e => setSelectedProjectId(e.target.value)} className="rounded-lg border bg-white px-3 py-2 text-sm"><option value="">Choisir un travail</option>{projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select><input value={planName} onChange={e => setPlanName(e.target.value)} placeholder="Nom du Delivery Plan" className="rounded-lg border bg-white px-3 py-2 text-sm"/><button onClick={savePlan} className="flex items-center gap-2 rounded-lg px-4 py-2 text-xs font-bold text-white" style={{ backgroundColor: accent }}><Save size={14}/> Enregistrer le plan</button></div><div className="flex flex-wrap items-center justify-between gap-2"><div className="flex items-center gap-2 rounded-lg border px-3 py-2"><Search size={15} className="text-slate-400"/><input value={deliverySearch} onChange={e => setDeliverySearch(e.target.value)} placeholder="Rechercher dans le plan..." className="w-72 max-w-full text-sm outline-none"/></div><div className="flex items-center gap-2 text-xs font-bold text-slate-600"><span>{deliveryTotal || filteredRows.length} ligne(s) stockée(s) — page {deliveryPage + 1}</span><span>CBM page : <b className="text-teal-700">{totalCbm.toFixed(4)} m³</b></span><button onClick={() => void loadDeliveryRows(planId, deliverySheet, Math.max(0, deliveryPage - 1), deferredDeliverySearch)} disabled={deliveryPage <= 0} className="rounded-lg border bg-white px-2 py-1 disabled:opacity-40">Précédent</button><button onClick={() => void loadDeliveryRows(planId, deliverySheet, deliveryPage + 1, deferredDeliverySearch)} disabled={(deliveryPage + 1) * deliveryPageSize >= deliveryTotal} className="rounded-lg border bg-white px-2 py-1 disabled:opacity-40">Suivant</button><button onClick={async () => { const result = await window.rubaDesktop?.exportDeliveryRowsCsv?.({ planId }); if (result) setMessage(`Export CSV créé : ${result.rows} ligne(s).`); }} className="rounded-lg border border-blue-200 bg-white px-2 py-1 text-blue-700">Exporter CSV</button><button onClick={deleteSelectedRows} disabled={!selectedRows.length} className="flex items-center gap-1 rounded-lg bg-rose-600 px-3 py-2 text-white disabled:opacity-40"><Trash2 size={14}/> Supprimer ({selectedRows.length})</button><button onClick={() => void openDeliveryManager()} className="flex items-center gap-1 rounded-lg border border-violet-300 bg-violet-700 px-3 py-2 text-white"><Database size={14}/> Gestion des données</button></div></div><div className="max-h-[68vh] overflow-x-scroll overflow-y-scroll rounded-xl border" onPaste={handlePaste} style={{ scrollbarGutter: 'stable both-edges', overscrollBehavior: 'contain' }}><table className="min-w-[3100px] table-fixed text-left text-xs"><thead className="sticky top-0 z-20 bg-slate-900 text-[10px] uppercase text-white"><tr><th className="sticky left-0 z-30 w-[48px] bg-slate-900 px-2 py-3"><CheckSquare size={14}/></th>{deliveryColumns.map(column => <th key={column.key} style={{ width: column.width, minWidth: column.width }} className="whitespace-nowrap border-l border-white/15 px-2 py-3">{column.label}</th>)}</tr><tr className="sticky top-[38px] z-20 bg-slate-100 text-slate-700"><th className="sticky left-0 z-30 bg-slate-100 px-2 py-1"><Filter size={13}/></th>{deliveryColumns.map(column => <th key={column.key} style={{ width: column.width, minWidth: column.width }} className="border-l border-slate-200 px-1 py-1"><input value={filters[column.key] || ''} onChange={e => setFilters(previous => ({ ...previous, [column.key]: e.target.value }))} placeholder="Filtrer..." className="w-full rounded border border-slate-300 bg-white px-1.5 py-1 text-[10px] font-normal text-slate-700 outline-none" /></th>)}</tr></thead><tbody>{filteredRows.map(row => <tr key={row.id} className="border-t hover:bg-teal-50/40"><td className="sticky left-0 z-10 bg-white p-1 text-center"><input type="checkbox" checked={selectedRows.includes(row.id)} onChange={() => toggleSelected(row.id)} /></td>{deliveryColumns.map(column => <td key={column.key} className="border-l border-slate-100 p-1"><input type={column.kind === 'number' ? 'number' : 'text'} inputMode={column.kind === 'date' ? 'text' : undefined} readOnly={column.key === 'cbm'} value={String(row[column.key] ?? '')} onChange={e => updateRow(row.id, column.key, e.target.value)} className={`w-full rounded border px-2 py-1.5 text-xs ${column.key === 'cbm' ? 'bg-teal-50 font-bold text-teal-800' : 'bg-white'}`} /></td>)}</tr>)}</tbody></table></div><div className="flex flex-wrap gap-2"><button onClick={() => setRows(previous => [...previous, normalizeRow({})])} className="flex items-center gap-2 rounded-lg border px-3 py-2 text-xs font-bold"><Plus size={14}/> Ajouter une ligne</button><button onClick={async () => { if (!window.confirm('Vider toutes les lignes du Delivery Plan ?')) return; if (window.rubaDesktop?.clearDeliveryRows && planId) await window.rubaDesktop.clearDeliveryRows(planId); setRows([normalizeRow({})]); setDeliveryTotal(0); setSelectedRows([]); setFilters({}); setMessage('Delivery Plan vidé dans SQLite.'); }} className="flex items-center gap-2 rounded-lg border px-3 py-2 text-xs font-bold"><RefreshCw size={14}/> Vider la grille</button><span className="flex items-center gap-2 rounded-lg bg-blue-50 px-3 py-2 text-xs font-semibold text-blue-800"><Download size={14}/> Collez une plage depuis Excel avec en-têtes. Les données sont enregistrées dans SQLite.</span></div></div>}
    {tab === 'settings' && <div className="space-y-5 p-5"><div className="rounded-2xl border border-slate-200 p-5"><h3 className="font-black">Stockage local</h3><p className="mt-2 break-all text-xs text-slate-500">{storageRoot || 'Stockage local de Ruba'}</p><button onClick={chooseRoot} className="mt-3 flex items-center gap-2 rounded-lg border px-4 py-2 text-xs font-bold"><FolderOpen size={14}/> Modifier le dossier</button></div><div className="rounded-2xl border border-slate-200 p-5"><h3 className="font-black">Thème et couleurs</h3><div className="mt-4 flex items-center gap-3"><input type="color" value={accent} onChange={e => saveAccent(e.target.value)} className="h-10 w-14 cursor-pointer rounded border"/><span className="text-sm font-semibold text-slate-700">Couleur principale des boutons et rubans</span><button onClick={() => saveAccent('#0f766e')} className="flex items-center gap-2 rounded-lg border px-3 py-2 text-xs font-bold"><Save size={14}/> Réinitialiser</button></div></div></div>}
    {showDeliveryManager && <div className="fixed inset-0 z-[80] flex items-center justify-center bg-slate-950/70 p-4" role="dialog" aria-modal="true"><div className="flex max-h-[90vh] w-full max-w-6xl flex-col rounded-2xl border border-violet-300/30 bg-white shadow-2xl"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 bg-gradient-to-r from-indigo-950 to-violet-900 px-5 py-4 text-white"><div><h3 className="font-black">Gestion des données — Delivery Plan</h3><p className="mt-1 text-xs text-indigo-200">{managerTotal.toLocaleString('fr-FR')} ligne(s) stockée(s) dans SQLite</p></div><button type="button" onClick={() => setShowDeliveryManager(false)} className="rounded-lg border border-white/20 px-3 py-1.5 text-xs font-bold hover:bg-white/10">Fermer</button></div><div className="flex flex-wrap items-center justify-between gap-2 border-b border-slate-200 bg-slate-50 p-4"><div className="flex items-center gap-2 rounded-lg border bg-white px-3 py-2"><Search size={14} className="text-slate-400"/><input value={managerSearch} onChange={e => { setManagerSearch(e.target.value); void refreshDeliveryManager(0, e.target.value); }} placeholder="Rechercher commande, client, PO, couleur..." className="w-80 max-w-full text-xs outline-none"/></div><div className="flex flex-wrap items-center gap-2"><button type="button" onClick={() => void refreshDeliveryManager()} className="flex items-center gap-1 rounded-lg border bg-white px-3 py-2 text-xs font-bold"><RefreshCw size={14}/> Mise à jour</button><button type="button" onClick={deleteManagerRows} disabled={!managerSelected.length} className="flex items-center gap-1 rounded-lg bg-rose-600 px-3 py-2 text-xs font-bold text-white disabled:opacity-40"><Trash2 size={14}/> Supprimer ({managerSelected.length})</button><button type="button" onClick={clearDeliveryDatabase} disabled={!managerTotal} className="rounded-lg border border-rose-300 px-3 py-2 text-xs font-bold text-rose-700 disabled:opacity-40">Vider le Delivery Plan</button></div></div><div className="min-h-0 flex-1 overflow-auto"><table className="w-full min-w-[900px] text-left text-xs"><thead className="sticky top-0 z-10 bg-slate-900 text-[10px] uppercase text-white"><tr><th className="w-10 px-3 py-3"><input type="checkbox" checked={managerRows.length > 0 && managerSelected.length === managerRows.length} onChange={e => setManagerSelected(e.target.checked ? managerRows.map(row => row.id) : [])}/></th><th className="px-3 py-3">Commande</th><th className="px-3 py-3">Client</th><th className="px-3 py-3">PO</th><th className="px-3 py-3">Couleur</th><th className="px-3 py-3">Destination</th><th className="px-3 py-3">PO QTY</th></tr></thead><tbody>{managerRows.map(row => <tr key={row.id} className="border-b border-slate-100 hover:bg-violet-50"><td className="px-3 py-2"><input type="checkbox" checked={managerSelected.includes(row.id)} onChange={() => setManagerSelected(previous => previous.includes(row.id) ? previous.filter(id => id !== row.id) : [...previous, row.id])}/></td><td className="px-3 py-2 font-mono font-bold text-indigo-800">{String(row.orderNumber || row.customerCode || '')}</td><td className="px-3 py-2">{String(row.customerName || '')}</td><td className="px-3 py-2">{String(row.customerPo || '')}</td><td className="px-3 py-2">{String(row.color || '')}</td><td className="px-3 py-2">{String(row.destination || row.dest || '')}</td><td className="px-3 py-2 font-bold">{String(row.poQty || '')}</td></tr>)}{!managerRows.length && <tr><td colSpan={7} className="px-4 py-12 text-center text-slate-500">Aucune ligne trouvée.</td></tr>}</tbody></table></div><div className="flex items-center justify-between border-t border-slate-200 bg-slate-50 px-4 py-3 text-xs font-bold text-slate-600"><span>Page {managerPage + 1} / {Math.max(1, Math.ceil(managerTotal / 250))}</span><div className="flex gap-2"><button type="button" disabled={managerPage <= 0} onClick={() => { const page = managerPage - 1; setManagerPage(page); void refreshDeliveryManager(page); }} className="rounded-lg border bg-white px-3 py-1.5 disabled:opacity-40">Précédent</button><button type="button" disabled={(managerPage + 1) * 250 >= managerTotal} onClick={() => { const page = managerPage + 1; setManagerPage(page); void refreshDeliveryManager(page); }} className="rounded-lg border bg-white px-3 py-1.5 disabled:opacity-40">Suivant</button></div></div></div></div>}
  </section>;
}
